// The comparison editor keeps an unapplied draft separate from the authoritative rules.
const CRITERIA_FIELDS=[['target','intakeCriteriaTarget','목표 평균 두께 (nm)','0.001'],['tolerance','intakeCriteriaTolerance','평균 허용차 (±nm)','0'],['cvLimit','intakeCriteriaCV','두께 CV 상한 (%)','0'],['areaLimit','intakeCriteriaArea','OM 얼룩 의심 면적 상한 (%)','0'],['particleDensityLimit','intakeCriteriaDensity','검출 영역 밀도 상한 (개/1만 px)','0']];
let criteriaDraft=null,criteriaBaseline=null,criteriaMessage='',criteriaTone='';
function criteriaValues(rule,policy){return {target:rule.target,tolerance:rule.tolerance,cvLimit:rule.cvLimit,areaLimit:policy.areaLimit,particleDensityLimit:policy.particleDensityLimit};}
function criteriaSignature(values){return JSON.stringify(CRITERIA_FIELDS.map(([key])=>values[key]));}
function resetCriteriaDraft(){criteriaDraft=null;criteriaBaseline=null;criteriaMessage='';criteriaTone='';}
function validateCriteria(values){const rule=M.validateRule(values),areaLimit=M.number(values.areaLimit),particleDensityLimit=M.number(values.particleDensityLimit);if(areaLimit===null||areaLimit<0||areaLimit>100)throw new Error('OM 얼룩 의심 면적 상한은 0~100%로 입력하세요.');if(particleDensityLimit===null||particleDensityLimit<0)throw new Error('검출 영역 밀도 상한은 0 이상의 숫자로 입력하세요.');return {...rule,areaLimit,particleDensityLimit};}
function criteriaEditorHTML(rule,policy){
 const current=criteriaValues(rule,policy),signature=criteriaSignature(current);
 if(criteriaBaseline!==signature){criteriaDraft=null;criteriaBaseline=signature;criteriaMessage='';criteriaTone='';}
 const values=criteriaDraft||current;
 return '<div id="intakeCriteria" class="intake-current-criteria"><b>현재 판정 기준</b><div class="intake-criteria-summary">평균 '+fmt(rule.target-rule.tolerance,1)+'~'+fmt(rule.target+rule.tolerance,1)+' nm · 두께 CV ≤ '+fmt(rule.cvLimit,1)+'%<br>OM 얼룩 의심 면적 ≤ '+fmt(policy.areaLimit,1)+'% · 검출 영역 밀도 ≤ '+fmt(policy.particleDensityLimit,1)+'개/1만 px</div><div class="intake-criteria-grid">'+CRITERIA_FIELDS.map(([key,id,label,min])=>'<label class="intake-field" for="'+id+'">'+label+'<input id="'+id+'" data-criteria-field="'+key+'" type="number" min="'+min+'"'+(key==='areaLimit'?' max="100"':'')+' step="any" value="'+esc(values[key]??'')+'"></label>').join('')+'</div><div class="intake-criteria-actions"><button type="button" id="intakeCriteriaApply" class="intake-primary">기준 적용</button><button type="button" id="intakeCriteriaCancel">변경 취소</button><span>전체 시편에 공통 적용</span></div><p id="intakeCriteriaFeedback" class="intake-criteria-feedback" data-tone="'+esc(criteriaTone)+'" role="status" aria-live="polite">'+esc(criteriaMessage)+'</p><p class="intake-criteria-note">판정 상한 변경은 충족 여부에 반영됩니다. 검출 영역·개수는 유지됩니다.</p></div><p class="intake-policy-note">초기 운영 기준 · OM 자동 판정 · 예외는 사용자 검토</p>';
}
function setCriteriaFeedback(message,tone=''){criteriaMessage=message;criteriaTone=tone;const feedback=$('intakeCriteriaFeedback');if(feedback){feedback.textContent=message;feedback.dataset.tone=tone;}}
function captureCriteriaDraft(){criteriaDraft=Object.fromEntries(CRITERIA_FIELDS.map(([key,id])=>[key,$(id).value]));setCriteriaFeedback('변경 대기 · 기준 적용을 누르면 반영됩니다.','pending');return {...criteriaDraft};}
function applyCriteria(values){
 const next=validateCriteria(values),surface=window.Hfo2Surface;
 if(typeof surface?.applyJudgmentLimits!=='function')throw new Error('OM 설정을 불러오는 중입니다. 잠시 후 다시 적용하세요.');
 // Validate all five fields before committing. The surface API also validates before mutation.
 surface.applyJudgmentLimits({areaLimit:next.areaLimit,particleDensityLimit:next.particleDensityLimit},{emit:false});
 for(const [key,id] of [['target','wfTarget'],['tolerance','wfTolerance'],['cvLimit','wfCV']])$(id).value=String(next[key]);
 criteriaDraft=null;criteriaBaseline=criteriaSignature(next);criteriaMessage='기준 적용 완료 · 판정 결과 갱신';criteriaTone='success';
 B.refresh();document.dispatchEvent(new CustomEvent('surface-reviewed'));
 return next;
}
