function combinedCounts(assessments){return '<div class="intake-combined-counts">'+[['pass','기준 충족','두께·OM 모두 충족'],['pending','검토 대기','자료 부족·기준 영역·추가 검토'],['fail','기준 초과','두께 또는 OM 기준 초과']].map(([state,label,detail])=>'<div class="intake-combined-count '+state+'"><span>'+label+'</span><b>'+assessments.filter(a=>a.state===state).length+'<small>/ '+assessments.length+' 시편</small></b><p>'+detail+'</p></div>').join('')+'</div>';}
function thicknessCounts(assessments){return '<div class="intake-combined-counts" data-assessment-scope="thickness">'+[['pass','두께 적합','평균 두께·CV 모두 기준 이내'],['pending','판정 대기','두께 자료 부족·입력 확인 필요'],['fail','두께 부적합','평균 두께 또는 CV 기준 초과']].map(([state,label,detail])=>'<div class="intake-combined-count '+state+'" data-thickness-state="'+state+'"><span>'+label+'</span><b>'+assessments.filter(a=>a.state===state).length+'<small>/ '+assessments.length+' 시편</small></b><p>'+detail+'</p></div>').join('')+'</div>';}
