 for(const g of groups){if(!g.candidate)continue;cards+='<div class="intake-candidate intake-candidate-pass" data-condition-rank="'+g.priority_rank+'"><h4>'+(g.preferred_candidate?'<span class="intake-pill">우선 검토 조건</span> ':'')+esc(g.concentration_M+' M · '+g.coats+'회 코팅')+' <span class="intake-pill">'+sourceName(g.data_source)+'</span></h4><p>'+esc(g.rpm+' rpm · '+g.spin_time_s+'초 · 어닐링 '+g.anneal_temp_C+'°C / '+g.anneal_time_min+'분')+'</p><p><strong>충족 '+g.combined_pass+' / 전체 '+g.count+'시편 ('+fmt(g.combined_pass/g.count*100,1)+'%)</strong> · 미충족 '+g.combined_fail+' ('+fmt(g.combined_fail/g.count*100,1)+'%) · 대기 '+g.combined_pending+'</p><p class="intake-subtle">우선순위 '+g.priority_rank+' · 판정 완료 '+g.decided_count+'시편 · 시편별 CV 평균 '+fmt(g.mean_sample_cv)+'%</p><div class="intake-candidate-samples">'+g.passing_sample_ids.map(id=>combinedBadge('pass',id)).join('')+'</div><p class="intake-condition-note">'+(g.data_source==='SYNTHETIC'?'기능 확인용 결과 · 실험 최적값 아님':g.count===1?'단일 시편 · 반복 검증 필요':'입력 시편의 기준 충족 현황 · 최적 Recipe 확정 아님')+'</p></div>';}
